export const BODY: string = "\n<p>تصویر پر فلٹر لگانے میں صرف چند منٹ لگتے ہیں۔ آپ تصویر اپ لوڈ کرتے ہیں، کوئی انداز چنتے ہیں، اس کی شدت طے کرتے ہیں اور پھر سجی ہوئی تصویر ڈاؤن لوڈ کر لیتے ہیں۔</p>\n<p>یہ رہنما ہر مرحلہ تفصیل سے بتاتا ہے۔ اس میں فلٹر گرڈ، شدت کا سلائیڈر، اصل تصویر سے موازنے کے اوزار اور ایکسپورٹ کی وہ ترتیبات شامل ہیں جن سے نتیجہ صاف ستھرا رہتا ہے۔</p>\n<p>آخر تک آپ کسی پورٹریٹ، منظر یا کھانے کی تصویر کو ہر ڈیوائس پر ایک جیسے انداز میں سجا سکیں گے۔ نتیجہ جانچنے تک اصل تصویر اپنے پاس محفوظ رکھیں۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: موڈ چنیں</h2>\n<p>اوزار کھولنے سے پہلے طے کریں کہ آپ کو کیسا موڈ چاہیے۔ گرم اور پرانی یادوں والا احساس ونٹیج یا سیپیا کے ساتھ بنتا ہے، جبکہ ڈرامائی احساس کے لیے بلیک اینڈ وائٹ نوار یا ڈراماٹک بہتر رہتا ہے۔</p>\n<p>سوچیں کہ تصویر کہاں دکھائی جائے گی۔ سوشل فیڈ کو ایک مستقل انداز چاہیے، جبکہ ایک اکیلی پرنٹ کے لیے صرف وہ فلٹر کافی ہے جو اس ایک تصویر کو سوٹ کرے۔</p>\n<p>اصل تصویر استعمال کریں، کمپریس شدہ کاپی نہیں۔ تیز اصل پر لگایا گیا فلٹر صاف لگتا ہے، جبکہ نرم کاپی پر وہی فلٹر کھردرا دکھائی دیتا ہے۔ <a href=\"/ur/tasveer-filters/\">Image Filters ٹول</a> براؤزر میں کھولیں، سب کچھ آپ کے آلے پر چلتا ہے۔</p>\n<h2 id=\"step-by-step\">پانچ مرحلوں میں تصویر پر فلٹر لگائیں</h2>\n<p>ہر فلٹر انداز کے لیے طریقہ ایک جیسا ہے۔ اپ لوڈ کریں، گرڈ میں دیکھیں، شدت طے کریں، اصل سے موازنہ کریں اور ڈاؤن لوڈ کریں۔</p>\n<p>شدت طے کرتے وقت جلدی نہ کریں۔ اکثر کم شدت مکمل شدت سے زیادہ خوبصورت لگتی ہے، اور پیش نظارہ فوراً بتا دیتا ہے کہ اثر کب ٹھیک لگ رہا ہے۔</p>\n<ol>\n<li>تصویر کو ڈراپ زون میں گھسیٹ کر، اپنے آلے سے چن کر یا Ctrl+V سے اسکرین شاٹ پیسٹ کر کے اپ لوڈ کریں۔</li>\n<li>فلٹر گرڈ دیکھیں اور اپنی تصویر پر پیش نظارہ دیکھنے کے لیے ونٹیج، وارم، سیپیا یا بلیک اینڈ وائٹ نوار جیسا کوئی انداز چنیں۔</li>\n<li>Filter Intensity سلائیڈر گھسیٹ کر شدت طے کریں، اصل کے لیے 0 فیصد سے مکمل اثر کے لیے 100 فیصد تک۔</li>\n<li>Hold to View Original یا اسپلٹ موازنے سے فلٹر والی تصویر کو اصل کے ساتھ جانچیں۔</li>\n<li>ایکسپورٹ فارمیٹ اور کوالٹی چنیں، پھر Download پر کلک کر کے فلٹر والی تصویر محفوظ کریں۔</li>\n</ol>\n<p>شیئر کرنے سے پہلے ڈاؤن لوڈ شدہ فائل ایک بار کھول کر دیکھیں۔ یقین کریں کہ فلٹر اچھا لگ رہا ہے اور تصویر کا اصل موضوع صاف نظر آ رہا ہے۔</p>\n<h2 id=\"browsing-filter-grid\">فلٹر گرڈ دیکھنا</h2>\n<p>فلٹر گرڈ میں گیارہ اندازوں میں سے ہر ایک کے نیچے آپ کی تصویر کا زندہ تھمب نیل دکھائی دیتا ہے۔ تھمب نیل آپ کی اصل تصویر سے بنتے ہیں، اس لیے کلک کرنے سے پہلے ہی پتا چل جاتا ہے کہ ہر فلٹر کیا کرے گا۔</p>\n<p>گرڈ کو آہستہ آہستہ دیکھیں اور تھمب نیلوں پر غور کریں۔ صحیح فلٹر فوراً نمایاں ہو جاتا ہے، کیونکہ وہ تصویر کے موڈ سے میل کھاتا ہے۔</p>\n<p>کسی ٹائل پر کلک کریں تو وہ فلٹر بڑے کینوس پر لگ جاتا ہے۔ بڑا پیش نظارہ مکمل اثر دکھاتا ہے، جسے چھوٹے تھمب نیل سے بہتر پرکھا جا سکتا ہے۔ اگر کوئی فلٹر نمایاں نہ ہو تو پہلے ونٹیج آزمائیں۔</p>\n<h2 id=\"setting-intensity\">فلٹر کی شدت طے کرنا</h2>\n<p>شدت صفر سے سو فیصد تک ہوتی ہے۔ سو فیصد پر مکمل فلٹر دکھائی دیتا ہے، جبکہ صفر فیصد پر تصویر بالکل ویسی کی ویسی رہتی ہے۔</p>\n<p>سو فیصد سے کم شدت پر فلٹر والے پکسلز اصل کی طرف واپس مل جاتے ہیں۔ پینتالیس فیصد پر ونٹیج ہلکی فلمی دھند دیتا ہے اور جلد کے رنگوں پر حاوی نہیں ہوتا۔</p>\n<p>پہلے فلٹر کو سو فیصد پر دیکھیں تاکہ اس کی شخصیت سمجھ آئے، پھر شدت کم کرتے جائیں جب تک اثر ٹھیک نہ لگے۔ پورٹریٹ کے لیے چالیس سے ساٹھ فیصد شدت عام طور پر بہترین رہتی ہے۔</p>\n<h2 id=\"comparing-with-original\">اصل تصویر سے موازنہ</h2>\n<p>فوری جانچ کے لیے Hold to View Original استعمال کریں۔ دبا کر رکھیں تو اصل تصویر دکھائی دیتی ہے، چھوڑیں تو فلٹر والی، اور فرق فوراً واضح ہو جاتا ہے۔</p>\n<p>باریک جانچ کے لیے اسپلٹ موازنہ بہتر ہے۔ اس میں اصل اور فلٹر والی تصویر ساتھ ساتھ دکھائی دیتی ہیں، اس لیے صاف پتا چلتا ہے کہ کن حصوں میں تبدیلی آئی ہے۔</p>\n<p>موازنے میں جلد، آسمان اور سائے ضرور دیکھیں۔ ایسا فلٹر جو پس منظر پر اچھا لگے، چہرے کو نارنجی یا آسمان کو سفید کر سکتا ہے۔ اگر فلٹر والی تصویر اصل سے بدتر لگے تو شدت کم کریں۔</p>\n<h2 id=\"using-vintage\">ونٹیج فلٹر استعمال کرنا</h2>\n<p>ونٹیج پہلے سے منتخب شدہ فلٹر ہے، تصویر اپ لوڈ کرتے ہی یہ سو فیصد پر لگا ہوتا ہے۔ اس کے مدھم رنگ اور نرم کنٹراسٹ سے ہلکی پرانی فلمی جھلک بنتی ہے۔</p>\n<p>ہلکے اثر کے لیے ونٹیج کو پچاس فیصد پر آزمائیں۔ مدھم جھلک برقرار رہتی ہے، مگر تصویر اپنے قدرتی رنگ زیادہ رکھتی ہے، جو پورٹریٹ اور روزمرہ تصویروں کو سوٹ کرتا ہے۔</p>\n<p>ونٹیج آرام دہ تصویروں، سوشل پوسٹوں اور یادوں کے لیے موزوں ہے۔ یہ گرم اور مانوس محسوس ہوتا ہے، اسی لیے یہ سب سے مقبول فلٹر ہے۔ اگر یہ زیادہ مدھم لگے تو وارم یا گولڈن آور آزمائیں۔</p>\n<h2 id=\"using-black-white\">گری اسکیل اور بلیک اینڈ وائٹ نوار</h2>\n<p>گری اسکیل رنگ ہٹا کر صاف بلیک اینڈ وائٹ تصویر دے دیتا ہے۔ یہ عمارتوں، اسٹریٹ فوٹوگرافی اور ہر اس تصویر کے لیے موزوں ہے جہاں شکل رنگ سے زیادہ اہم ہو۔</p>\n<p>بلیک اینڈ وائٹ نوار رنگ ہٹانے کے ساتھ سخت کنٹراسٹ بھی جوڑ دیتا ہے۔ کالے گہرے ہو جاتے ہیں، سفید روشن ہو جاتے ہیں اور تصویر میں فلمی ڈرامائی کیفیت آ جاتی ہے۔</p>\n<p>جب تصویر پرسکون اور دستاویزی لگنی چاہیے تو گری اسکیل چنیں، اور جب ڈرامائی لگنی چاہیے تو بلیک اینڈ وائٹ نوار چنیں۔ بلیک اینڈ وائٹ کے بعد کنٹراسٹ ضرور جانچیں، کیونکہ رنگ ہی گہرائی کا کچھ حصہ اٹھا رہا تھا۔</p>\n<h2 id=\"using-warm-cool\">وارم اور کول فلٹر استعمال کرنا</h2>\n<p>وارم سنہری رنگت جوڑتا ہے جس سے تصویر دھوپ والی اور خوش آمدید محسوس ہوتی ہے۔ یہ پورٹریٹ، کھانے اور مناظر کے لیے موزوں ہے، جہاں گرم چمک تصویر کو دلکش بناتی ہے۔</p>\n<p>کول نیلی رنگت جوڑتا ہے جس سے تصویر پرسکون اور صاف محسوس ہوتی ہے۔ یہ سردی کے مناظر، عمارتوں اور ٹیکنالوجی مصنوعات کے لیے موزوں ہے، جہاں ٹھنڈا پیلیٹ جدید لگتا ہے۔</p>\n<p>ایک ہی تصویر پر دونوں آزما کر موازنہ کریں۔ فرق فوراً واضح ہو جاتا ہے، اور صحیح والا منظر کا حصہ محسوس ہوتا ہے۔ گرم روشنی والی تصویر پر وارم فلٹر قدرتی چمک بڑھاتا ہے۔</p>\n<h2 id=\"filters-for-portraits\">پورٹریٹ کے لیے فلٹر</h2>\n<p>پورٹریٹ کو نرم فلٹر درمیانی شدت پر سوٹ کرتے ہیں۔ چالیس سے ساٹھ فیصد پر ونٹیج، وارم اور میٹ فیڈ موڈ جوڑتے ہیں مگر چہرہ نہیں بدلتے، جو پورٹریٹ کی اصل ضرورت ہے۔</p>\n<p>پورٹریٹ پر ہائی کنٹراسٹ اور ڈراماٹک سے بچیں، جب تک موڈ اس کا تقاضا نہ کرے۔ سخت سائے چہرے کو عمر رسیدہ اور جلد کو کھردرا دکھا سکتے ہیں۔</p>\n<p>مضبوط تاثرات والے پورٹریٹ پر بلیک اینڈ وائٹ نوار خوب جچتا ہے۔ ڈرامائی بلیک اینڈ وائٹ آنکھوں اور جذبات کو نمایاں کرتا ہے۔ ہر فلٹر کے بعد جلد کے رنگ ضرور جانچیں۔</p>\n<h2 id=\"filters-for-food\">کھانے کی تصویروں کے لیے فلٹر</h2>\n<p>کھانے کی تصویروں کو وارم اور گولڈن آور فلٹر سوٹ کرتے ہیں، جو بھرپور اور بھوک بڑھانے والے رنگ نمایاں کرتے ہیں۔ گرم چمک کھانوں کو تازہ اور دلکش دکھاتی ہے۔</p>\n<p>کھانے کے لیے چالیس سے ساٹھ فیصد درمیانی شدت استعمال کریں۔ مکمل شدت رنگوں کو مصنوعی بنا سکتی ہے، جبکہ ہلکا فلٹر انہیں قدرتی انداز میں نکھارتا ہے۔</p>\n<p>کھانے کی تصویروں پر کول سے بچیں۔ نیلی رنگت کھانوں کو ٹھنڈا اور بے ذائقہ دکھاتی ہے، جو کھانے کی تصویر کے مقصد کے الٹ ہے۔ فلٹر کے بعد سرخ رنگ ضرور جانچیں۔</p>\n<h2 id=\"previewing\">ڈاؤن لوڈ سے پہلے پیش نظارہ</h2>\n<p>ڈاؤن لوڈ سے پہلے ہمیشہ پیش نظارہ دیکھیں۔ یقین کریں کہ فلٹر اچھا لگ رہا ہے، موضوع صاف نظر آ رہا ہے اور جلد کے رنگ قدرتی ہیں۔</p>\n<p>اصل سے فوری موازنے کے لیے ہولڈ بٹن استعمال کریں۔ اکیلا اچھا لگنے والا فلٹر اصل کے ساتھ غلط لگ سکتا ہے، اور ہولڈ موازنہ یہ فوراً دکھا دیتا ہے۔</p>\n<p>جلد، آسمان اور سائے کو مکمل سائز میں زوم کر کے دیکھیں۔ ان حصوں میں فلٹر کی خرابیاں سب سے پہلے نظر آتی ہیں، اور چھوٹا پیش نظارہ انہیں چھپا سکتا ہے۔ اگر فلٹر زیادہ سخت لگے تو شدت دس فیصد کم کریں۔</p>\n<h2 id=\"choosing-export-format\">ایکسپورٹ فارمیٹ چننا</h2>\n<p>شیئر کرنے والی تصویروں کے لیے JPG چنیں۔ اس کا فائل سائز چھوٹا رہتا ہے، یہ ہر جگہ چلتا ہے اور اونچی کوالٹی پر فلٹر والی تصویر صاف رہتی ہے۔</p>\n<p>شفافیت والے گرافکس اور لوگو کے لیے PNG چنیں۔ PNG بغیر نقصان والا فارمیٹ ہے، اس لیے رنگ بالکل درست رہتے ہیں اور شفاف حصے محفوظ رہتے ہیں۔</p>\n<p>چھوٹی فائل اور اچھی کوالٹی چاہیے تو WebP چنیں۔ یہ ویب تصویروں کے لیے بہترین ہے، اگرچہ چند پرانے نظام اب بھی اسے قبول نہیں کرتے۔ یاد رکھیں کہ PNG کے لیے کوالٹی سلائیڈر چھپ جاتا ہے۔</p>\n<h2 id=\"applying-on-mobile\">فون یا ٹیبلٹ پر فلٹر لگانا</h2>\n<p>یہ ٹول ٹچ اسکرین پر کام کرتا ہے، اس لیے آپ اسی فون پر تصویر سجا سکتے ہیں جس سے وہ لی گئی تھی۔ گیلری سے اپ لوڈ کریں، فلٹر ٹائل پر ٹیپ کریں اور نتیجہ ڈاؤن لوڈ کریں۔</p>\n<p>فون پر فلٹر گرڈ دیکھنا آسان ہے۔ تھمب نیلوں پر ٹیپ کرتے جائیں، بڑا پیش نظارہ بدلتا جائے گا، پھر سلائیڈر سے شدت طے کریں۔</p>\n<p>ڈاؤن لوڈ سے پہلے پیش نظارہ مکمل سائز میں ضرور دیکھیں۔ فون کی چھوٹی اسکرین پر ٹھیک لگنے والا فلٹر کمپیوٹر پر زیادہ سخت لگ سکتا ہے۔</p>\n<h2 id=\"troubleshooting\">عام فلٹر مسائل کا حل</h2>\n<p>اگر فلٹر زیادہ سخت لگے تو شدت کم کریں۔ سو فیصد پر ونٹیج تصویر پر حاوی ہو سکتا ہے، جبکہ پچاس فیصد پر وہی فلٹر موضوع چھپائے بغیر موڈ جوڑ دیتا ہے۔</p>\n<p>اگر جلد نارنجی یا سبز لگے تو فلٹر پورٹریٹ کو سوٹ نہیں کر رہا۔ ونٹیج یا میٹ فیڈ جیسا نرم فلٹر آزمائیں، یا شدت کم کر دیں۔</p>\n<p>اگر تصویر اصل سے بدتر لگے تو Reset پر کلک کر کے فلٹر ہٹا دیں۔ فلٹر کو تصویر بہتر بنانی چاہیے، صرف بدلنی نہیں چاہیے۔ اگر ڈاؤن لوڈ پیش نظارے سے مختلف لگے تو فارمیٹ اور کوالٹی جانچیں۔</p>\n<h2 id=\"consistent-feed\">فلٹر سے مستقل فیڈ بنانا</h2>\n<p>ایک فلٹر اور ایک شدت چنیں اور پوری سیریز میں وہی استعمال کریں۔ ہر تصویر پر پچاس فیصد ونٹیج والی فیڈ ترتیب یافتہ لگتی ہے، جبکہ ملے جلے فلٹر بے ترتیب لگتے ہیں۔</p>\n<p>پابند ہونے سے پہلے فلٹر کو مختلف قسم کی تصویروں پر آزمائیں۔ مناظر کو سوٹ کرنے والا فلٹر پورٹریٹ کو سوٹ نہ کرے تو مستقل انداز نہیں بنتا۔</p>\n<p>اپنا فلٹر اور شدت لکھ کر رکھیں۔ ونٹیج پچاس فیصد جیسی مختصر نوٹ سے آپ ہر تصویر پر وہی انداز دہرا سکتے ہیں۔ کبھی کبھار اپنے فلٹر کا انتخاب دوبارہ دیکھیں۔</p>\n<h2 id=\"quick-tips\">بہتر فلٹر کے لیے فوری نکات</h2>\n<p>فلٹر کی شخصیت دیکھنے کے لیے پہلے مکمل شدت پر شروع کریں، پھر کم کرتے جائیں جب تک اثر ٹھیک نہ لگے۔ اکثر کم شدت مکمل اثر سے زیادہ خوبصورت لگتی ہے۔</p>\n<p>ہر فلٹر کے بعد جلد، آسمان اور سائے جانچیں۔ ان حصوں میں خرابیاں سب سے پہلے نظر آتی ہیں، اور چھوٹا پیش نظارہ انہیں چھپا سکتا ہے۔</p>\n<p>ایک تصویر پر ایک ہی فلٹر استعمال کریں۔ فلٹر والی تصویر دوبارہ اپ لوڈ کر کے فلٹر چڑھانے سے ہر مرحلے میں نقصان بڑھتا ہے۔ اصل تصویر بغیر فلٹر محفوظ رکھیں۔</p>\n<h2 id=\"filter-for-wedding-photo\">شادی کی تصویر پر فلٹر لگانا</h2>\n<p>شادی کی تصویروں کو نرم فلٹر سوٹ کرتے ہیں۔ چالیس سے پچاس فیصد پر ونٹیج یا میٹ فیڈ نرم رومانوی احساس جوڑتا ہے، بغیر چہرے یا سفید لباس بدلے۔</p>\n<p>شادی کی تصویروں پر سخت فلٹر سے بچیں۔ ہائی کنٹراسٹ اور ڈراماٹک جوڑے کو عمر رسیدہ اور لباس کو سرمئی دکھا سکتے ہیں، جو شادی کے البم کے لیے غلط ہے۔</p>\n<p>فلٹر کے بعد سفید لباس ضرور جانچیں۔ لباس کو پیلا یا گلابی کرنے والا فلٹر البم میں غلط لگتا ہے، اس لیے شدت کم کر دیں۔ پورے شادی سیٹ کے لیے ایک ہی فلٹر استعمال کریں۔</p>\n<p>موازنے کے لیے <a href=\"/ur/blog/photo-filters-muqabla/\">Photo Filters Compared: Choosing a Consistent Look</a> پڑھیں۔ مکمل رہنما کے لیے <a href=\"/ur/blog/tasveer-filters-rehnumai/\">Image Filters: Complete Guide</a> دیکھیں، اور پیش سیٹ کی بجائے رنگ ٹھیک ٹھیک بدلنے کے لیے <a href=\"/ur/tasveer-ki-saturation-badlein/\">Image Saturation Editor</a> آزمائیں۔</p>\n";

